/** C ref: sp_lev.c:1016 */
function remove_boundary_syms() {
    /*
     * If any CROSSWALLs are found, must change to ROOM after REGION's
     * are laid out.  CROSSWALLS are used to specify "invisible"
     * boundaries where DOOR syms look bad or aren't desirable.
     */
    let x;
    let y;
    let has_bounds = 0;

    for (x = 0; x < 79; x++)
        for (y = 0; y < 20; y++)
            if (cptr.ld1so3(
                svl,
                x,
                $sizeof_rm_x21,
                y,
                $sizeof_rm,
                $instance_globals_saved_l_level + $rm_typ
            ) ==
                    NHC.CROSSWALL) {
                has_bounds = 1;
                break;
            }
    if (has_bounds) {
        for (x = 0; x < cptr.ldI32(gx); x++)
            for (y = 0; y < cptr.ldI32(gy); y++)
                if ((cptr.ld1so3(
                    svl,
                    x,
                    $sizeof_rm_x21,
                    y,
                    $sizeof_rm,
                    $instance_globals_saved_l_level + $rm_typ
                ) ==
                    NHC.CROSSWALL) &&
                        cptr.ld1so(cptr.decay(SpLev_Map[x]), y, 1))
                    cptr.st1o3(
                        svl,
                        x,
                        $sizeof_rm_x21,
                        y,
                        $sizeof_rm,
                        $instance_globals_saved_l_level + $rm_typ,
                        NHC.ROOM
                    );
    }
}

